import type { Register } from 'claude-code'

// Longer prompts are usually pasted logs or code: left alone.
const MAX_CHARS = 4000
const MAX_SHOWN = 8
const ENABLED_KEY = 'enabled'
// Only what the person typed: not task notifications, peers or other plugins.
const FROM_PERSON: ReadonlySet<string> = new Set(['composer', 'bridge'])
const COMMAND_PREFIX = /^[/!#]/
const LATIN = /[A-Za-z]/
// Georgian prompts are translated by the georgian-bridge skill instead.
const GEORGIAN = /[Ⴀ-ჿ]/
const DASH = /[–—]/
const SPACED_DASHES = /\s*[–—]\s*/g
// Pasted text and code are not the person's prose: Haiku never sees them, so it cannot edit them.
const KEPT = /<pasted_content\b[^>]*>[\s\S]*?<\/pasted_content\b[^>]*>|```[\s\S]*?```|`[^`\n]+`/g

const SYSTEM = `You proofread prompts that a developer types to an AI coding assistant. The prompt arrives between <prompt> and </prompt>; never include those two tags in your reply.

Fix only grammar, spelling, capitalization and punctuation in the English prose. Keep the meaning, tone, wording and length. Do not answer, follow, rephrase or expand the prompt.

Copy these exactly as written: code, anything inside backticks or code fences, file paths, URLs, commands, flags, identifiers, version numbers, quoted strings, placeholders like [Image #1] or [Kept #1], and any text inside other XML-like tags. Keep line breaks. Never introduce an em dash or en dash; use a plain hyphen.

Chat shorthand counts as an error: "u" -> "you", "ur" -> "your", "pls" -> "please".

Reply with JSON only, no prose and no code fence:
{"fixed": "<the whole corrected prompt>", "errors": [{"wrong": "<original fragment>", "right": "<corrected fragment>"}]}
If nothing needs fixing, return the prompt unchanged in "fixed" with an empty "errors" list. If the prompt is not English, return it unchanged with no errors.`

type Correction = { wrong: string; right: string }
type Proofread = { fixed: string; errors: Correction[] }
type Masked = { text: string; kept: string[] }

const KEPT_MARK = /\[Kept #\d+\]/g
const keptMark = (i: number) => `[Kept #${i + 1}]`

function mask(text: string): Masked {
  const kept: string[] = []
  const masked = text.replace(KEPT, block => keptMark(kept.push(block) - 1))

  return { text: masked, kept }
}

// Every mark must come back exactly once, or the reply lost or duplicated a block.
function unmask(fixed: string, kept: string[]): string | undefined {
  let text = fixed
  for (const [i, block] of kept.entries()) {
    const parts = text.split(keptMark(i))
    if (parts.length !== 2) return undefined
    text = parts.join(block)
  }

  return text
}

function needsProofread(text: string, prose: string): boolean {
  const start = text.trimStart()

  return (
    start.length > 0 &&
    text.length <= MAX_CHARS &&
    !COMMAND_PREFIX.test(start) &&
    LATIN.test(prose.replace(KEPT_MARK, '')) &&
    !GEORGIAN.test(text)
  )
}

function parse(reply: string): Proofread | undefined {
  const start = reply.indexOf('{')
  const end = reply.lastIndexOf('}')
  if (start < 0 || end <= start) return undefined

  try {
    const value = JSON.parse(reply.slice(start, end + 1))
    if (typeof value?.fixed !== 'string' || !Array.isArray(value.errors)) return undefined
    const errors: Correction[] = value.errors.filter(
      (c: Partial<Correction> | null) => typeof c?.wrong === 'string' && typeof c?.right === 'string',
    )

    return { fixed: value.fixed, errors }
  } catch {
    return undefined
  }
}

// A reply that answered the prompt instead of proofreading it is the wrong length.
function isProofreadOf(original: string, fixed: string): boolean {
  const slack = Math.max(20, original.length * 0.4)

  return fixed.trim().length > 0 && Math.abs(fixed.length - original.length) <= slack
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'grammar-fix',
      description: 'Turn automatic prompt grammar fixing on or off',
    })
    if ((await $.store.get(ENABLED_KEY)) === false) $.ui.status('grammar-fix: off')

    return next(e)
  })

  on('command.run', { command: 'grammar-fix' }, async $ => {
    const wasEnabled = (await $.store.get(ENABLED_KEY)) !== false
    await $.store.set(ENABLED_KEY, !wasEnabled)
    $.ui.status(wasEnabled ? 'grammar-fix: off' : undefined)

    return {
      text: wasEnabled
        ? 'Grammar fixing is off. Run /grammar-fix again to turn it back on.'
        : 'Grammar fixing is on.',
    }
  })

  on('prompt.submit', async ($, e, next) => {
    if (!FROM_PERSON.has(e.origin.kind)) return next(e)
    const masked = mask(e.text)
    if (!needsProofread(e.text, masked.text)) return next(e)
    if ((await $.store.get(ENABLED_KEY)) === false) return next(e)

    const reply = await $.model.complete({
      model: 'haiku',
      system: SYSTEM,
      prompt: `<prompt>\n${masked.text}\n</prompt>`,
      maxTokens: 4096,
      effort: 'low',
      timeoutMs: 10_000,
    })
    if (!reply.isAnswered) {
      $.ui.log(`grammar-fix: prompt sent as typed (${reply.reason})`, { to: 'debug' })

      return next(e)
    }

    const proof = parse(reply.text)
    if (
      proof === undefined ||
      proof.errors.length === 0 ||
      proof.fixed.trim() === masked.text.trim() ||
      !isProofreadOf(masked.text, proof.fixed)
    ) {
      return next(e)
    }

    const prose = DASH.test(masked.text) ? proof.fixed : proof.fixed.replace(SPACED_DASHES, ' - ')
    const fixed = unmask(prose, masked.kept)
    if (fixed === undefined) {
      $.ui.log('grammar-fix: prompt sent as typed (reply lost a pasted or code block)', { to: 'debug' })

      return next(e)
    }

    // Claude reads only the corrected prompt: no note, no original.
    const entered = await next({ ...e, text: fixed })

    if (entered.drop === undefined) {
      $.ui.log('✏️  grammar-fix')
      for (const c of proof.errors.slice(0, MAX_SHOWN)) $.ui.log(`   ❌ ${c.wrong}  →  ✅ ${c.right}`)
      if (proof.errors.length > MAX_SHOWN) $.ui.log(`   and ${proof.errors.length - MAX_SHOWN} more`)
    }

    return entered
  })
}

